CD.tables.forEach(function(t,ti){if(!t.ids||!t.h.slice(1).some(function(h){return /Связка|Ядро|Сфера|Карты/.test(h);}))return;t.rows.forEach(function(r,i){var ids=[];t.ids[i].slice(1).forEach(function(c){c.forEach(function(x){if(ids.indexOf(x)<0)ids.push(x);});});if(ids.length>=2&&!t.ids[i][0].length&&!PR.some(function(p){return p.name===r[0];}))PR.push({g:'t'+ti,name:r[0],ids:ids.slice(0,4),t:t.h.slice(1).map(function(h,k){return h+': '+r[k+1];}).join('. ')});});});
