if(TCR.length>=6)T.push({id:'tcard',title:O.tcTitle||'Карта в теме урока',fmt:'смысл → карта',desc:'Дан смысл карты в теме этого урока. Выберите, какая карта так читается.',mode:'mcq',count:Math.min(TCR.length,20),
 gen:function(){var x=P(TCR);var w=SH(TCR.filter(function(y){return y.id!==x.id;}));var seen={},ws=[];w.forEach(function(y){if(!seen[y.id]&&ws.length<3){seen[y.id]=1;ws.push(D.name(y.id));}});return mcq(x.h+': «'+x.m+'». Какая это карта?',D.name(x.id),ws,{e:'Таблица «'+x.tb+'».',img:null});}});
// contrast sort
var CTB=CD.tables.filter(function(t){return t.h.length>=3&&t.rows.length>=3&&t.h.slice(1).some(function(h){return /если|Бытов|можно|нельзя|Тень|Чаще|Наведён/i.test(h);});});
if(CTB.length)T.push({id:'tsort',title:O.tsTitle||'Разложите признаки',fmt:'разложите по группам',desc:'Признаки и формулировки из таблиц урока. Разложите каждую в свою колонку.',mode:'sort',count:Math.min(CTB.length*3,10),
 gen:function(){var t=P(CTB);var it=[];t.rows.forEach(function(r){for(var k=1;k<t.h.length;k++)if(r[k]&&!/^#/.test(r[k]))it.push({t:r[0].replace(/^#.*/,'')+': '+r[k],b:k-1});});return {q:'Таблица «'+t.h.join(' · ')+'». Разложите по колонкам.',buckets:t.h.slice(1),items:SH(it).slice(0,8)};}});
