if(SPOS.length)T.push({id:'sim',title:'Расклад-тренажёр',fmt:'случайные карты в раскладах урока',desc:'Выпадает один из раскладов урока со случайными картами. Прочитайте каждую позицию письменно, потом откройте подсказку по карте.',mode:'spread',count:6,
 gen:function(){var s=P(SPOS);var cs=SH(D.cards.map(function(c){return c.id;})).slice(0,s.items.length).map(function(x){return Math.random()<(O.revRate||0)?x+'r':x;});return {story:'Расклад «'+s.sec.replace(/^Расклад\s*/,'').replace(/[«»]/g,'')+'». '+(O.simStory||''),q:'Прочитайте каждую позицию, затем откройте подсказку.',positions:s.items.map(function(x){return x[0]+(x[1]?': '+x[1]:'');}),cards:cs,hints:cs.map(hint),summary:'Соберите ответ из трёх–пяти предложений: что происходит, откуда трудность, что делать. Каждое предложение должно опираться на карту, которую можно показать.'};}});
